// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2019, "4-5", [{"author":"Е. Бикмаев","question":"Люба рассказывает друзьям: «Я сегодня видела жука — вот такущего!» Люба имеет в виду, что жук был … .","choices":["чёрный","круглый","крупный","маленький","ползущий."],"key":"В","review":["Жук Любы","Прочитай слово «такущего» как выразительное «вот такого большого». В таком рассказе размер часто показывают и жестом.","Реплика описывает крупного жука. Цвет, форма и способ передвижения из неё не следуют. Выбираем вариант В."]},{"author":"Л. Фёдорова","question":"Саша выполняет упражнение с заданием вставить в предложения пропущенные существительные в нужной форме.\n1) <em>Пришли зимние _____</em>. 2) <em>Подули весенние _____</em>.\n3) <em>Полили осенние _____</em>. 4) <em>Настали летние _____</em>.\nКакое существительное нельзя вставить ни в одно из данных предложений?","choices":["<em>дождь</em>","<em>холод</em>","<em>тепло</em>","<em>ветер</em>","<em>день</em>."],"key":"В","review":["Времена года в пропусках","Прочитай каждое предложение с подходящим словом. Пришли зимние холода, подули весенние ветры, полили осенние дожди, настали летние дни.","Все четыре места требуют множественного числа. В значении погоды «тепло» употребляется в единственном числе — «настало летнее тепло». В заданные предложения это слово не подходит, вариант В."]},{"author":"Е. Бикмаев","question":"Посмотрите на две картинки, которые Вася нашёл в интернете по одному и тому же слову. Какое слово он набрал в интернете?","choices":["<em>школа</em>","<em>аудитория</em>","<em>класс</em>","<em>перемена</em>","<em>каникулы</em>."],"key":"В","review":["Две картинки из поиска","На левой картинке помещение с партами и доской. В школе его можно назвать классом.","На правой картинке большие пальцы подняты в знак одобрения. Этот жест передаёт восклицание «Класс!». Обе картинки подходят к слову «класс» из варианта В."],"figure":{"condition":{"src":"assets/medvezhonok/2019/4-5-3.svg","width":642,"height":206,"alt":"На одной картинке кабинет с партами, на другой несколько рук с поднятыми большими пальцами."}}},{"author":"М. Рубинштейн","question":"Какое слово обозначает то, что вы можете получить и в кассе магазина, и в драке?","choices":["<em>деньги</em>","<em>товар</em>","<em>мелочь</em>","<em>сдача</em>","<em>скидка</em>."],"key":"Г","review":["В магазине и в драке","Если покупатель дал денег больше, чем стоит покупка, кассир возвращает разницу. Она называется сдачей.","Удар в ответ тоже могут назвать сдачей — «дать сдачи» или «получить сдачу». Два значения совпали у слова из варианта Г."]},{"author":"Б. Иомдин и М. Иомдин","question":"<em>«Не ... меня!» — сказала мама Мише</em>. Заполните пропуск.","choices":["<em>щекотай</em>","<em>щекоти</em>","<em>щекочи</em>","<em>щекоть</em>","<em>щекочь</em>."],"key":"В","review":["Просьба мамы","Мама обращается к одному человеку и просит прекратить действие. Для этого нужна повелительная форма глагола «щекотать».","У «щекотать» в этой форме происходит чередование т и ч. Нормативная фраза «Не щекочи меня!» получается с вариантом В."]},{"author":"И. Иткин","question":"Латинские буквы <strong>p</strong> и <strong>q</strong> обладают некоторой особенностью, которой, кроме них, обладает ещё только одна пара латинских букв. Какая?","choices":["<strong>a</strong> и <strong>z</strong>","<strong>b</strong> и <strong>d</strong>","<strong>d</strong> и <strong>t</strong>","<strong>n</strong> и <strong>u</strong>","<strong>r</strong> и <strong>s</strong>."],"key":"Б","review":["Пары латинских букв","Представь строчные p и q по разные стороны вертикального зеркала. Их длинные черты направлены вниз, а округлые части смотрят в разные стороны.","У букв b и d отражение тоже меняет сторону округлой части. Их длинные черты направлены вверх. «n и u» можно сопоставить поворотом. Зеркальную пару даёт вариант Б."]},{"author":"Б. Иомдин","question":"Как не говорят о времени?","choices":["<em>без двадцати пять</em>","<em>без четверти шесть</em>","<em>половина второго</em>","<em>треть восьмого</em>","<em>четверть десятого</em>."],"key":"Г","review":["Как называют время","Проверь выражения по часам. «Без двадцати пять» — 4:40, «без четверти шесть» — 5:45, «половина второго» — 1:30, а «четверть десятого» — 9:15.","Для 7:20 обычно говорят «двадцать минут восьмого». Целый час можно делить на три части по 20 минут, но выражение «треть восьмого» для времени не употребляют. Ответ Г."]},{"author":"Л. Фёдорова","question":"Какое из ряда существительных склоняется не совсем так, как остальные?","choices":["<em>бедро</em>","<em>ведро</em>","<em>весло</em>","<em>крыло</em>","<em>ребро.</em>"],"key":"Г","review":["Формы множественного числа","Образуй множественное число. Получаются «бёдра», «вёдра», «вёсла», «крылья» и «рёбра».","Просклоняй слова во множественном числе. «Бёдра — бёдер», «вёдра — вёдер», «вёсла — вёсел», «рёбра — рёбер» меняются по одной модели. У слова «крыло» получается «крылья — крыльев» со звуком [й’] после мягкого [л’]. Это вариант Г."]},{"author":"Е. Муравенко","question":"Где бывают трещины, морщины, щели?","choices":["на лбу, на чашке, в заборе","на лбу, в заборе, на чашке","в заборе, на лбу, на чашке","в заборе, на чашке, на лбу","на чашке, на лбу, в заборе."],"key":"Д","review":["Повреждения и складки","Морщины появляются на коже, например на лбу. Щели — промежутки между частями предмета, например между досками забора.","Трещина бывает на чашке, когда материал надломился. Порядок «на чашке, на лбу, в заборе» указан в варианте Д."]},{"author":"Л. Фёдорова","question":"В какой паре глаголы могут быть синонимами?","choices":["<em>закопать — вскопать</em>","<em>заплыть — всплыть</em>","<em>задуть — вздуть</em>","<em>закипеть — вскипеть</em>","<em>завинтить — взвинтить</em>."],"key":"Г","review":["Глаголы с приставками","Для каждой пары придумай ситуацию. Закопать — спрятать в земле, а вскопать — разрыхлить землю. Заплыть — попасть куда-то вплавь, всплыть — подняться на поверхность. Задуть свечу и вздуть пузырь, завинтить гайку и взвинтить цену — разные действия.","Про один и тот же чайник можно сказать «вода закипела» и «вода вскипела». Оба глагола здесь означают начало кипения. Ответ Г."]},{"author":"Е. Муравенко","question":"Из каждого данного слова, убрав две соседние буквы внутри слова, можно получить название животного. Но только в одном случае количество слогов в новом слове останется прежним. В каком?","choices":["<em>барабан</em>","<em>корень</em>","<em>королева</em>","<em>крокет</em>","<em>листва</em>."],"key":"Д","review":["Звери внутри слов","По очереди убирай две соседние буквы. Получатся бара[ба]н → баран, ко[ре]нь → конь, коро[ле]ва → корова, кро[ке]т → крот. Во всех четырёх случаях мы зачеркнули по одной гласной, поэтому слогов стало меньше.","В слове лис[тв]а вычёркиваются две согласные. Получается «лиса» с теми же двумя слогами. Значит, подходит «листва», вариант Д."]},{"author":"Л. Фёдорова","question":"<em>Я извинился, но это</em> ... . Как <strong>нельзя</strong> закончить фразу?","choices":["<em>ничему не помогло</em>","<em>ничего не помогло</em>","<em>никак не помогло</em>","<em>ничуть не помогло</em>","фразу можно закончить любым из предложенных в (А)–(Г) способов."],"key":"Б","review":["Что изменили извинения","Глагол «помочь» сочетается с вопросом «кому? чему?». Этим объясняется выражение «ничему не помогло». Слова «никак» и «ничуть» уточняют, в какой мере это помогло.","К слову «ничего» задают вопрос «чего?», а для этого смысла требуется «чему?». Поэтому сочетание «это ничего не помогло» в задании не подходит. Ответ Б."]},{"author":"Б. Иомдин и М. Иомдин","question":"<em>— Давайте искать Слонопотама, — предложил Пятачок.</em>\n<em>— Я за! Двумя руками! — сказал Кристофер Робин.</em>\n<em>— А я ... лапами! — воскликнул Винни-Пух.</em>\nЗаполните пропуск.","choices":["<em>четверьмя</em>","<em>четырьмя</em>","<em>четвермя</em>","<em>четырмя</em>","<em>четверымя</em>."],"key":"Б","review":["Пух и Слонопотам","Кристофер Робин говорит, что поддерживает идею двумя руками. Пух подхватывает шутку и хочет использовать для поддержки все четыре лапы.","К слову «четыре» подбери форму для вопроса «чем? сколькими лапами?». Получается «четырьмя лапами», вариант Б."]},{"author":"Е. Бикмаев","question":"Знайка — герой известной детской сказки — был … коротышкой.","choices":["нарисованным","начитанным","написанным","надуманным","насчитанным."],"key":"Б","review":["Сказочный коротышка","Имя Знайки связано со словом «знать». В сказке он любил читать и много знал из книг.","Человека, который много прочитал, называют начитанным. «Знайка был начитанным коротышкой» — вариант Б."]},{"author":"Б. Иомдин","question":"Вася выделил во всех данных ниже словах суффикс <em>-ок</em>. В каком слове он ошибся?","choices":["<em>замок</em>","<em>звонок</em>","<em>игрок</em>","<em>свисток</em>","<em>дружок</em>."],"key":"А","review":["Суффикс под проверкой","Проверь, можно ли объяснить слово через родственное. Звонок связан со звоном, игрок играет, свисток служит для свиста, дружок — ласковое обращение к другу.","В слове «замок» при обоих ударениях, за́мок и замо́к, буквы ок входят в корень. Отдельного суффикса -ок здесь нет. Вася ошибся в варианте А."]},{"author":"Б. Иомдин и М. Иомдин","question":"Бабушка приготовила два блюда. Миша хочет съесть побольше того и другого и при этом не сделать ошибки. Как ему лучше закончить просьбу к бабушке: «Положи мне, пожалуйста, ...».","choices":["<em>голубец и холодец</em>","<em>голубца и холодца</em>","<em>голубцов и холодцов</em>","<em>голубцы и холодцы</em>","<em>голубцы и холодец.</em>"],"key":"Д","review":["Обед у бабушки","Голубцы можно посчитать поштучно. Миша просит несколько штук, поэтому подходит форма множественного числа «голубцы».","Холодец обычно подают порциями одного блюда. В такой просьбе используют единственное число «холодец». «Положи мне голубцы и холодец» — вариант Д."]},{"author":"С. Сай","question":"В каком случае прилагательное, обозначающее принадлежность к стране, может быть получено из названия страны не совсем так, как в остальных случаях?","choices":["<em>Дания</em>","<em>Испания</em>","<em>Румыния</em>","<em>Эстония</em>","<em>Япония</em>."],"key":"А","review":["Названия стран","Сравни пары «Испания — испанский», «Румыния — румынский», «Эстония — эстонский» и «Япония — японский». В каждом прилагательном узнаётся начало названия страны без конечного -ия.","Дания без -ия даёт «дан-», а в современном прилагательном «датский» перед -ск- стоит т. Основа изменилась, поэтому отличается Дания, вариант А."]},{"author":"Б. Иомдин","question":"Какого слова нет?","choices":["<em>комариный</em>","<em>осиный</em>","<em>гусиный</em>","<em>утиный</em>","<em>паутиный</em>."],"key":"Д","review":["Прилагательные от животных","От названий комара, осы, гуся и утки образуются прилагательные «комариный», «осиный», «гусиный» и «утиный».","Для паука есть «паучий», а для чего-то похожего на паутину можно сказать «паутинный» с двумя н. Формы «паутиный» нет, вариант Д."]},{"author":"Е. Муравенко","question":"В каком из двустиший Самуила Маршака пропущены одинаковые буквы?","choices":["Эй, не стойте слишком бли__ко —\nЯ тигрёнок, а не ки__ка.","И жить на свете будут вро__ь\nБарсук и лев, медведь и ло__ь.","Вот теперь попали в ро__!\nЧто за пряник — чистый мё__.","Повернись на правый бо__,\nДам овса тебе мешо__.","Бедный маленький верблю__:\nЕсть ребёнку не даю__."],"key":"Г","review":["Пропуски в двустишиях","Восстанови слова в каждой паре. В первых трёх получаем «близко — киска», «врозь — лось», «рот — мёд». В последней — «верблюд — дают».","В оставшейся паре «на правый бок — мешок овса» обе недостающие буквы — к. Это двустишие из варианта Г."]},{"author":"И. Рубанов","question":"<em>В финале турнира по боксу Петров ... Иванова.</em> В этой фразе мы пропустили одно слово. Какое?","choices":["<em>проиграл</em>","<em>выиграл</em>","<em>победил</em>","<em>уступил</em>","невозможно определить: подходят варианты (Б) и (В)."],"key":"В","review":["Петров против Иванова","Проверь, какого падежа требует каждый глагол. Можно проиграть или уступить кому? Иванову. Можно выиграть у кого? У Иванова.","Глагол «победить» требует прямого дополнения — победить кого? Иванова. Здесь подходит только «победил», вариант В."]},{"author":"Б. Гуревич","question":"Пол подметая, задела кота я,\nЧёрным покрытого лаком.\nХвостик, изогнутый как __________,\nСтал __________.\n\nВ стихотворении Зои Эзрохи мы пропустили названия … .","choices":["двух разных букв","двух разных цифр","двух разных математических знаков","двух разных знаков препинания","математического знака и знака препинания."],"key":"Г","review":["Хвост кота в стихах","Вначале хвост изогнут, как вопросительный знак. Когда кота задели, хвост выпрямился, как восклицательный.","Проверка по рифме даёт «лаком — знаком». Обе формы хвоста названы знаками препинания. Это вариант Г."]},{"author":"Л. Фёдорова","question":"Кого называют <em>долговязым</em>?","choices":["паука","того, кто долго говорит","того, кто долго думает","того, кто высок, худощав и нескладен","того, кто увяз в долгах."],"key":"Г","review":["Слово о внешности","Слово «долговязый» применяют к человеку, чей рост и сложение бросаются в глаза. Так часто описывают высокого подростка с длинными руками и ногами.","Слово также передаёт худобу и некоторую нескладность. Такое объяснение дано в варианте Г."]},{"author":"Е. Бикмаев","question":"В сказке Николая Носова о приключениях Незнайки хулиганы-коротышки решили затеять что-нибудь __________, поэтому натянули верёвку поперёк дороги, чтобы кто-нибудь споткнулся и упал. Какое прилагательное мы пропустили?","choices":["<em>умопомрачительное</em>","<em>несносное</em>","<em>сумасбродное</em>","<em>сногсшибательное</em>","<em>развлекательное</em>."],"key":"Г","review":["Верёвка поперёк дороги","Коротышки натянули верёвку, чтобы прохожий споткнулся. Получится, что верёвка буквально собьёт человека с ног.","В слове «сногсшибательное» спряталось выражение «сшибить с ног». Оно годится и для обычного значения «потрясающее», и для шутки с верёвкой. Ответ Г."]},{"author":"П. Аркадьев, И. Иткин и А. Панина","question":"В японском языке есть глаголы со значением ‘играть на ударных инструментах’, ‘играть на духовых инструментах’ и ‘играть на струнных инструментах’. Выберите вариант, где эти глаголы перечислены в правильном порядке:","choices":["хику, фуку, татаку","фуку, татаку, хику","хику, татаку, фуку","татаку, хику, фуку","татаку, фуку, хику."],"key":"Д","review":["Японские глаголы и музыка","В слове «татаку» слышно «та-та», как два коротких удара. По-японски этот глагол значит «стучать, ударять». «Фуку» означает «дуть» и напоминает русское «фукнуть», поэтому подходит для духовых.","Остаётся «хику». Японцы употребляют этот глагол, когда играют на струнных инструментах. Порядок «татаку, фуку, хику» дан в варианте Д."]},{"author":"И. Иткин","question":"В финале стихотворения Семёна Кирсанова описан вымышленный мир, в котором у людей вместо имён — номера из букв и цифр:\nЯ хотела вам признаться,\nчто люблю вас, R-13!\nОтвечаю, умилён:\nЯ люблю вас, У-_____!\n\nКакое число мы пропустили в последней строке стихотворения?","choices":["0","13","666","1 000 000","987 654 321."],"key":"Г","review":["Номера в стихотворении","Произнеси R-13 как «эр-тринадцать». Конец строки «тринадцать» рифмуется со словом «признаться».","После «умилён» нужен похожий звук и подходящее число слогов. «Миллион» подходит по ритму и рифме, это 1 000 000. Ответ Г."]},{"author":"И. Рубанов","question":"<em>Дорога</em>, <em>карьер</em>, <em>отмель</em>, <em>пирожное</em>, <em>часы</em>. Какие из этих слов чаще сочетаются с прилагательным <em>песочный</em>, чем с прилагательным <em>песчаный</em>?","choices":["<em>дорога</em> и <em>карьер</em>","<em>карьер</em> и <em>отмель</em>","<em>отмель</em> и <em>пирожное</em>","<em>пирожное</em> и <em>часы</em>","<em>часы</em> и <em>дорога</em>."],"key":"Г","review":["Два прилагательных о песке","Когда речь идёт о покрытии или грунте, обычно говорят «песчаная дорога», «песчаный карьер», «песчаная отмель».","Для пирожного из особого теста употребляют «песочное», а для часов с пересыпающимся песком — «песочные». Совпала пара «пирожное и часы» в варианте Г."]},{"author":"Л. Фёдорова","question":"Какой из глаголов, описывающих пение соловья в следующем старинном стихотворении, сейчас звучит не совсем так, как раньше?\n\nСвистал на кустике когда-то Соловей\nВсей силою своей:\nУрчал, дробил, визжал, кудряво, густо, тонко,\nПорывно, косно вдруг, вдруг томно, нежно, звонко,\nСтенал, хрипел, щелкал, скрипел, тянул, вилял,\nИ разностью такой людей и птиц пленял.\n[М. И. Попов. Соловей (1772)]","choices":["<em>урчал</em>","<em>дробил</em>","<em>щелкал</em>","<em>тянул</em>","<em>вилял</em>."],"key":"В","review":["Старинное пение соловья","Прочитай строку в ритме стихотворения. У соседних глаголов ударение падает на второй слог — стена́л, хрипе́л, скрипе́л, тяну́л, виля́л.","Ритм требует читать «щелка́л». Сегодня в этом слове ударение ставят на первый слог и произносят «щёлкал». Изменившаяся форма дана в варианте В."]},{"author":"Б. Иомдин","question":"Найдите в тексте этой задачи слог, повторяющийся три раза, подставьте его к слогам, данным в ответах, и получите существующие слова. С каким слогом так сделать не получится?","choices":["<em>чи</em>","<em>сте</em>","<em>ве</em>","<em>кре</em>","<em>ма</em>."],"key":"Б","review":["Слог из текста задачи","Начальный слог «сло» есть в словах «сло-гам», «сло-ва» и «сло-гом». Само слово «слог» состоит из одного слога целиком, вместе с конечной согласной.","Если прибавить «сло» справа, получатся «число», «весло», «кресло» и «масло». Со слогом «сте» слова не выходит. Подходит вариант Б."]},{"author":"И. Рубанов и С. Сай","question":"Петя гулял четыре часа. За первый час он прошёл ... километра, за второй — ... километра, за третий — ... километра, за четвёртый — … километра. На месте многоточий стоят названия четырёх <strong>разных</strong> чисел, причём каждое из этих названий состоит из одного слова. Сколько всего километров прошёл Петя?","choices":["десять","десять с половиной","одиннадцать","одиннадцать с половиной","двенадцать."],"key":"Б","review":["Четыре часа ходьбы","Форма «километра» нужна после «два», «три» и «четыре». Из однословных чисел подходит ещё «полтора», то есть один с половиной.","Петя каждый раз проходит разное расстояние. Складываем все четыре — 2 + 3 + 4 + 1,5 = 10,5 километра. Это вариант Б."]},{"author":"Е. Бикмаев","question":"В мультфильме «Лягушка-путешественница» по сказке В. М. Гаршина утка, расхваливая юг, говорит: «Юг — это ____, напоминающий ____». Второе пропущенное слово можно получить из первого, вычеркнув в нём первую букву. Какая это буква?","choices":["<em>к</em>","<em>о</em>","<em>с</em>","<em>в</em>","<em>у</em>."],"key":"А","review":["Рассказ утки о юге","Второе слово должно хвалить юг и называть прекрасное место. Подходит «рай».","Перед словом «рай» поставь к. Из него получится «край», и фраза «Юг — это край, напоминающий рай» сохраняет смысл и порядок слов. Выбираем к, вариант А."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
